Te = 1;

num1 = [10];
den1 = [1 10 0];
[numd1, dend1] = c2dm(num1, den1, Te, 'zoh');
G1 = tf(numd1, dend1, Te) %[output:71fd6129]

num2 = [1];
den2 = [1 2];
[numd2, dend2] = c2dm([num2 0], den2, Te, 'zoh');
G2 = tf([numd2 0], conv(dend2, [1 -1]), Te) %[output:97f2484d]

G0 = series(G1, G2) %[output:92c8461d]

zplane(G0.Numerator{1},G0.Denominator{1}) %[output:332cfab1]


